pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 commitVal, uint256 newVal, address actor) public {
        // 1. wide admissible domain; only avoid the trivial zero-new-value collision
        newVal = bound(newVal, 1, type(uint256).max);
        vm.assume(actor != address(0));

        // 2. scenario: commit a value BEFORE initialization, then initialize,
        //    then a later SetMinSum(newVal) must revert and leave MinSum untouched.
        vm.startPrank(actor);
        c.SetMinSum(commitVal);   // succeeds (not yet initialized)
        c.Initialized();          // lock configuration
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // 3. single universal assertion: after initialization every SetMinSum reverts
        //    and MinSum stays exactly at the committed value.
        assertTrue(!ok && c.MinSum() == commitVal);
    }
}

